# Si aun asi se pasa del tope, se va soltando el relleno del final hasta caber: la cabecera,
# la ley, "a quien puede danar" y los trozos que traen la declaracion de una funcion pedida
# son LO NECESARIO, no se tocan.
aviso = ("AVISO: este material se recorto para que entrara. Puede faltar algun archivo entero. "
         "NO adivines lo que no ves: si te falta algo, contesta NECESITO_LEER seguido del "
         "archivo que hace falta.")
tope_trabajo = tope - len(aviso) - 1
recortado = False
_funciones = [f for f in (funciones or []) if f]
while len("\n".join(salida)) > tope_trabajo and len(salida) > len(bloques["__cabecera__"]):
    cabecera = len(bloques["__cabecera__"])
    ultimo = None
    for i in range(len(salida) - 1, cabecera - 1, -1):
        if salida[i].startswith("### `"):
            ultimo = i
            break
    if ultimo is not None:
        if _funciones and any(("def %s(" % f) in ln for ln in salida[ultimo:] for f in _funciones):
            # Este trozo trae la declaracion de una funcion pedida: se protege.
            # Se busca el trozo protegido anterior para seguir soltando por encima de el.
            anterior = None
            for k in range(ultimo - 1, cabecera - 1, -1):
                if salida[k].startswith("### `"):
                    anterior = k
                    break
            if anterior is None:
                break
            del salida[anterior:ultimo]
            recortado = True
        else:
            del salida[ultimo:]
            recortado = True
    else:
        if len(salida) <= cabecera:
            break
        salida.pop()
        recortado = True
if recortado:
    salida.append(aviso)
return "\n".join(salida)

